begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(20);
insert into employees(id,full_name,position) values('f1000000-0000-4000-8000-000000000001','Item owner','owner_admin'),('f1000000-0000-4000-8000-000000000002','Item cashier','kasir');
insert into suppliers(id,name) values('f2000000-0000-4000-8000-000000000001','Item supplier');
insert into categories(id,name) values('f3000000-0000-4000-8000-000000000001','Item category');
insert into subcategories(id,category_id,name) values('f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','Item subcategory');
insert into products(id,sku,name,base_unit,category_id,subcategory_id,cost_price) values('f5000000-0000-4000-8000-000000000001','ITEM-SNAPSHOT','Snapshot product','Tablet','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001',100),('f5000000-0000-4000-8000-000000000002','ITEM-UNPRICED','Unpriced master','Botol','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001',null);
insert into product_units(id,product_id,unit_name,conversion_to_base,selling_price,is_base_unit) values('f6000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000001','Tablet',1,133.2,true);
insert into purchase_invoices(id,supplier_id,invoice_number,invoice_date,total_amount,created_by,updated_by) values('f7000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','ITEM-INV','2026-10-29',1000,'f1000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001');
create temporary table before_items as select (select md5(coalesce(string_agg(row_to_json(p)::text,',' order by id),'')) from products p) products,(select md5(coalesce(string_agg(row_to_json(u)::text,',' order by id),'')) from product_units u) units,(select md5(coalesce(string_agg(row_to_json(b)::text,',' order by id),'')) from product_batches b) batches;
create function pg_temp.item_payload() returns jsonb language sql as $$select '{"product_id":"f5000000-0000-4000-8000-000000000001","product_unit_id":"f6000000-0000-4000-8000-000000000001","cost_price":"100.00","tax_rate":"11.00","selling_price":"133.20","margin_percent":null,"pricing_mode":"selling_price","quantity":"2","batch_number":"BATCH-A","expired_date":"2030-01-01"}'::jsonb$$;
select lives_ok($$select write_purchase_invoice_item('f7000000-0000-4000-8000-000000000001','f8000000-0000-4000-8000-000000000001','f9000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001',null,'create',pg_temp.item_payload())$$,'create item snapshot');
select is((select subtotal from purchase_invoice_items where id='f8000000-0000-4000-8000-000000000001'),222::numeric,'subtotal includes purchase tax');
select is((select unit_name_snapshot from purchase_invoice_items where id='f8000000-0000-4000-8000-000000000001'),'Tablet','unit snapshot comes from database');
select lives_ok($$select write_purchase_invoice_item('f7000000-0000-4000-8000-000000000001','f8000000-0000-4000-8000-000000000001','f9000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001',null,'create',pg_temp.item_payload())$$,'same request replays');
select is((select count(*)::integer from purchase_invoice_items where invoice_id='f7000000-0000-4000-8000-000000000001'),1,'retry does not duplicate');
select lives_ok($$select write_purchase_invoice_item('f7000000-0000-4000-8000-000000000001','f8000000-0000-4000-8000-000000000002',gen_random_uuid(),'f1000000-0000-4000-8000-000000000001',null,'create',pg_temp.item_payload()||'{"product_id":"f5000000-0000-4000-8000-000000000002","product_unit_id":null}')$$,'master without sale unit has explicit invoice prices');
select ok((select product_unit_id is null and unit_name_snapshot='Botol' from purchase_invoice_items where id='f8000000-0000-4000-8000-000000000002'),'master gets no fictitious sale unit');
select lives_ok($$select write_purchase_invoice_item('f7000000-0000-4000-8000-000000000001','f8000000-0000-4000-8000-000000000003',gen_random_uuid(),'f1000000-0000-4000-8000-000000000001',null,'create',pg_temp.item_payload()||'{"batch_number":"BATCH-B"}')$$,'same product supports another batch');
select is((select count(*)::integer from purchase_invoice_items where invoice_id='f7000000-0000-4000-8000-000000000001'),3,'invoice contains multiple rows');
select lives_ok($$select write_purchase_invoice_item('f7000000-0000-4000-8000-000000000001','f8000000-0000-4000-8000-000000000001',gen_random_uuid(),'f1000000-0000-4000-8000-000000000001',1,'update',pg_temp.item_payload()||'{"quantity":"3"}')$$,'edit item snapshot');
select is((select version from purchase_invoice_items where id='f8000000-0000-4000-8000-000000000001'),2,'edit increments item version');
select throws_ok($$select write_purchase_invoice_item('f7000000-0000-4000-8000-000000000001','f8000000-0000-4000-8000-000000000001',gen_random_uuid(),'f1000000-0000-4000-8000-000000000001',1,'update',pg_temp.item_payload())$$,'P0001','INVOICE_ITEM_VERSION_CONFLICT','stale edit rejected');
select throws_ok($$select write_purchase_invoice_item('f7000000-0000-4000-8000-000000000001',gen_random_uuid(),gen_random_uuid(),'f1000000-0000-4000-8000-000000000002',null,'create',pg_temp.item_payload())$$,'P0001','FORBIDDEN','cashier cannot mutate item');
select lives_ok($$select write_purchase_invoice_item('f7000000-0000-4000-8000-000000000001','f8000000-0000-4000-8000-000000000003','f9000000-0000-4000-8000-000000000002','f1000000-0000-4000-8000-000000000001',1,'delete','{}')$$,'delete item');
select ok((select deleted_at is not null from purchase_invoice_items where id='f8000000-0000-4000-8000-000000000003'),'deleted item retained for retry identity');
select lives_ok($$select write_purchase_invoice_item('f7000000-0000-4000-8000-000000000001','f8000000-0000-4000-8000-000000000003','f9000000-0000-4000-8000-000000000002','f1000000-0000-4000-8000-000000000001',1,'delete','{}')$$,'delete retry is safe');
select ok(not has_table_privilege('authenticated','purchase_invoice_items','INSERT') and not has_function_privilege('authenticated','write_purchase_invoice_item(uuid,uuid,uuid,uuid,integer,text,jsonb)','EXECUTE'),'browser cannot write table or invoke RPC directly');
select lives_ok($$select write_purchase_invoice_item('f7000000-0000-4000-8000-000000000001','f8000000-0000-4000-8000-000000000004',gen_random_uuid(),'f1000000-0000-4000-8000-000000000001',null,'create',pg_temp.item_payload()||'{"cost_price":"12.50","tax_rate":"0","margin_percent":"16","selling_price":"14","pricing_mode":"margin"}')$$,'margin rounding matches existing JavaScript pricing helper');
select is((select selling_price from purchase_invoice_items where id='f8000000-0000-4000-8000-000000000004'),14::numeric,'rounding boundary is preserved');
select results_eq($$select (select md5(coalesce(string_agg(row_to_json(p)::text,',' order by id),'')) from products p),(select md5(coalesce(string_agg(row_to_json(u)::text,',' order by id),'')) from product_units u),(select md5(coalesce(string_agg(row_to_json(b)::text,',' order by id),'')) from product_batches b)$$,$$select * from before_items$$,'all stock and product prices unchanged');
select * from finish();
rollback;
